import archiver from 'archiver';
app.get('/bundle.zip', (req, res) => {
  res.attachment('bundle.zip');
  const zip = archiver('zip', { zlib: { level: 9 } });
  zip.on('error', (e) => res.status(500).end(e.message));
  zip.pipe(res);
  zip.file('/path/a.txt', { name: 'a.txt' });
  zip.append('hello', { name: 'b.txt' });
  zip.finalize();
});
